// Old model URLs from before a catalogue was re-read (refs corrected against the scans).
// The map is generated by scripts/model_redirects.py: a slug that no longer exists goes to the
// model that replaced it, or to the model search for the old reference — never to a guess.
// Too many entries for next.config redirects, so they are resolved here.

import { NextResponse, type NextRequest } from "next/server";
import redirects from "@/data/model-redirects.json";

const MAP = redirects as Record<string, string>;
const PREFIX = "/catalogue/model/";

export function proxy(req: NextRequest) {
  const slug = req.nextUrl.pathname.slice(PREFIX.length).replace(/\/+$/, "");
  const to = MAP[slug];
  if (!to) return NextResponse.next();
  return NextResponse.redirect(new URL(to, req.url), 308);
}

export const config = { matcher: "/catalogue/model/:slug" };
